add(kp,"CAS指令在现代并发编程中广泛用于（）。","实现无锁数据结构和原子操作",["文件管理","内存分配","设备驱动"],"CAS是无锁编程（Lock-Free Programming）的基础原语，广泛用于并发数据结构的实现。","中等")
add(kp,"以下关于“Fetch-and-Add”指令的描述，正确的是（）。","原子地从内存读取、加一个值、再写回",["不读取直接增加","用于文件操作","是软件方法"],"FAA（Fetch-and-Add）原子地完成读-加-写操作，常用来实现计数器和排队锁。","中等")
add(kp,"互斥的硬件方法中，锁变量在内存中，多核CPU通过（）保证原子性。","总线锁定或缓存锁定",["软件锁","关中断","信号量"],"多核CPU通过锁总线（LOCK#信号）或锁缓存行来保证读-改-写指令的原子性。")
