add(kp,"以下哪种情况属于“同步”而非“互斥”（）。","计算进程向打印进程发送打印完成信号",["两个进程竞争打印机","两个进程更新共享变量","两个进程读取同一文件"],"进程间发送信号（协作）是同步关系；竞争资源是互斥关系。","中等")
add(kp,"以下关于同步机制的“粒度”描述，正确的是（）。","细粒度同步并发度高但实现复杂，粗粒度同步简单但并发度低",["细粒度同步并发度低","粗粒度同步并发度高","粒度不影响并发度"],"细粒度锁（如每个数据项一个锁）并发高但开销大；粗粒度锁（如整个数据结构一个锁）简单但并发低。","中等")
add(kp,"“屏障”（Barrier）同步机制的作用是（）。","使一组进程都到达某点后再一起继续执行",["阻止进程进入临界区","阻塞一个进程","保护共享变量"],"屏障（Barrier）用于并行计算中的同步：所有线程到达屏障点后才能继续执行。")
