# 3.4.1 死锁的概念 (~55 questions)
# ===========================================
kp = "3.4.1"
add(kp,"死锁是指（）。","两个或多个进程因竞争资源而无限期相互等待的状态",["进程正常结束","一个进程阻塞","进程被终止"],"死锁（Deadlock）是多个进程因循环等待资源而永远无法继续执行的状态。")
add(kp,"以下关于死锁的描述，正确的是（）。","死锁中的进程无法自行解除，需要外部干预",["死锁会自动解除","死锁不影响进程执行","死锁只发生在单CPU"],"死锁中的进程处于无限等待状态，没有外力作用（如终止进程、回滚资源）无法解除。")
add(kp,"以下哪个场景最可能发生死锁（）。","两个进程各自持有对方需要的资源并等待",["一个进程使用完资源后释放","进程按顺序申请资源","进程不使用共享资源"],"死锁的典型场景：进程A持有资源R1等待R2，进程B持有资源R2等待R1，形成循环等待。")
add(kp,"以下关于死锁和饥饿的区别，描述正确的是（）。","死锁是进程无限等待，饥饿是进程长期等待但仍可能获得资源",["死锁和饥饿完全相同","饥饿比死锁更严重","饥饿是进程无限等待"],"饥饿（Starvation）中进程可能最终获得资源，只是等待时间很长；死锁永远无法获得。")
add(kp,"以下关于死锁的“可抢占资源”和“不可抢占资源”，描述正确的是（）。","可抢占资源可以从持有者手中强行拿走，不可抢占资源不行",["所有资源都是可抢占的","所有资源都是不可抢占的","资源类型不影响死锁"],"可抢占资源（如CPU、内存）可以强行收回；不可抢占资源（如打印机、文件）必须等待释放。")
add(kp,"死锁通常发生在（）资源上。","不可抢占",["可抢占","所有类型","虚拟"],"死锁主要发生在不可抢占资源上，因为进程必须等待资源被主动释放。")
add(kp,"以下关于死锁的“资源分配图”描述，正确的是（）。","资源分配图中有环不一定死锁，但死锁一定有环",["有环就一定死锁","死锁不一定有环","资源分配图不能描述死锁"],"如果每种资源只有一个实例，有环即死锁；如果每种资源有多个实例，有环是死锁的必要不充分条件。","中等")
add(kp,"在资源分配图中，如果存在环且每种资源只有一个实例，则（）。","一定存在死锁",["不一定死锁","一定没有死锁","需要其他条件"],"每种资源只有一个实例时，资源分配图中的环是死锁的充要条件。")
add(kp,"在资源分配图中，如果存在环但每种资源有多个实例，则（）。","可能死锁也可能不死锁",["一定死锁","一定不死锁","死锁与资源数量无关"],"多实例资源时，环是死锁的必要条件不是充分条件，需要进一步判断。","中等")
add(kp,"以下关于死锁的“安全状态”描述，正确的是（）。","安全状态是指系统能按某种顺序为进程分配资源而不死锁",["安全状态一定死锁","不安全状态一定死锁","安全状态与死锁无关"],"安全状态（Safe State）存在安全序列，可以顺序满足所有进程的最大需求。","中等")
add(kp,"以下关于“安全状态”和“死锁”的关系，描述正确的是（）。","安全状态一定不会死锁，不安全状态可能死锁",["安全状态可能死锁","不安全状态一定死锁","两者没有关系"],"安全状态：存在安全序列，系统不会死锁；不安全状态：不一定死锁，但可能死锁。","中等")
add(kp,"死锁的“资源分配”方式中，以下哪种可能导致死锁（）。","一次性分配所需资源",["逐步分配资源","资源有序分配","资源预分配"],"一次性分配所有资源（预分配）可以防止死锁；逐步（动态）分配资源是死锁产生的前提。","中等")
add(kp,"以下关于死锁的描述，属于“死锁”而非“饥饿”的是（）。","哲学家问题中，每个哲学家都拿起一只筷子等待另一只",["低优先级进程长期得不到CPU","写者长期等待读者","进程等待打印机"],"哲学家全部拿起一只筷子等待另一只，形成循环等待，是死锁；长时间等待但最终可能获得是饥饿。","中等")
add(kp,"以下关于死锁的“系统模型”描述，正确的是（）。","系统模型包括进程、资源、分配关系",["只包括进程","只包括资源","不包括分配关系"],"死锁系统模型：进程集合P、资源集合R、分配边（资源→进程）、请求边（进程→资源）。")
add(kp,"死锁的“资源类型”可以分为（）。","可重用资源和可消耗资源",["硬件资源和软件资源","系统资源和用户资源","独享资源和共享资源"],"可重用资源（SR）：可被多个进程反复使用（如CPU、内存）；可消耗资源（CR）：使用后消失（如信号、消息）。")
add(kp,"以下关于可消耗资源导致死锁的经典例子，正确的是（）。","两个进程互相等待对方发送消息",["两个进程竞争CPU","两个进程竞争内存","两个进程竞争文件"],"可消耗资源（如消息）的死锁：进程A等待B发送消息，进程B等待A发送消息，互相等待。")
add(kp,"以下关于死锁的“联合进程图”（Joint Progress Diagram），描述正确的是（）。","展示两个进程的执行路径和死锁区域",["只展示一个进程","不能展示死锁","展示资源分配"],"联合进程图以两个进程的执行进度为坐标轴，展示不可达区域、死锁区域等。","中等")
add(kp,"以下关于死锁的“处理策略”，不属于OS采用的方法的是（）。","忽略死锁（鸵鸟策略）不是一种策略",["死锁预防","死锁避免","死锁检测与恢复"],"处理死锁的四种策略：预防（Prevention）、避免（Avoidance）、检测与恢复（Detection & Recovery）、忽略（Ostrich Algorithm）。","中等")
add(kp,"以下关于死锁“鸵鸟策略”的描述，正确的是（）。","假装死锁不会发生，不采取任何措施",["积极预防死锁","检测死锁并恢复","避免死锁"],"鸵鸟策略（Ostrich Algorithm）：忽视死锁问题，认为死锁发生概率极低，处理代价大于死锁代价。")
add(kp,"UNIX/Linux对死锁通常采用（）。","鸵鸟策略（忽略死锁）",["死锁预防","死锁避免","死锁检测"],"大多数通用操作系统（UNIX/Linux/Windows）采用鸵鸟策略，因为死锁预防/避免代价太大。")
add(kp,"以下关于死锁的“代价”描述，正确的是（）。","死锁预防和避免的代价可能比死锁本身的代价更大",["死锁没有代价","预防代价总是小于死锁代价","死锁无需处理"],"死锁预防/避免会降低系统并发度和资源利用率，其性能代价可能超过偶发死锁的影响。")
add(kp,"以下关于死锁的“资源分配”策略，描述正确的是（）。","死锁只在进程动态申请资源时可能发生",["资源不需要申请","动态申请不会死锁","静态分配也会死锁"],"如果进程在运行前一次性获取所有资源，就不会发生死锁；动态（逐步）申请是死锁产生的前提。")

# ===========================================
# 3.4.2 死锁的必要条件 (~55 questions)
# ===========================================
kp = "3.4.2"
add(kp,"死锁的四个必要条件是（）。","互斥、占有且等待、不可抢占、循环等待",["互斥、同步、通信、调度","互斥、共享、并发、异步","互斥、等待、释放、请求"],"死锁的四个必要条件（Coffman条件）：互斥（Mutual Exclusion）、占有且等待（Hold and Wait）、不可抢占（No Preemption）、循环等待（Circular Wait）。")
add(kp,"死锁必要条件中的“互斥条件”是指（）。","资源一次只能被一个进程使用",["资源可以同时被多个进程使用","进程之间互相排斥","所有资源都可以共享"],"互斥条件：至少有一个资源是不可共享的，一次只能被一个进程持有。")
add(kp,"死锁必要条件中的“占有且等待”是指（）。","进程持有至少一个资源同时等待其他资源",["进程不持有任何资源","进程只等待不持有","进程持有所有资源"],"占有且等待（Hold and Wait）：进程已持有某些资源，又申请新的资源并被阻塞。")
add(kp,"死锁必要条件中的“不可抢占”是指（）。","资源只能被持有者主动释放，不能被强行拿走",["资源可以被强行拿走","资源可以共享","资源不需要释放"],"不可抢占（No Preemption）：已分配给进程的资源不能被强制收回，只能等待进程主动释放。")
add(kp,"死锁必要条件中的“循环等待”是指（）。","存在进程资源的循环等待链",["进程按顺序等待","进程独立等待","进程不等待"],"循环等待（Circular Wait）：存在进程集合{P0,P1,...,Pn}，P0等待P1的资源，P1等待P2的资源...Pn等待P0的资源。")
add(kp,"以下关于死锁必要条件的描述，正确的是（）。","四个条件必须同时满足才会发生死锁",["满足一个条件即可死锁","只满足互斥即可死锁","必要条件互不相关"],"死锁的四个条件是必要且充分的（同时满足必然死锁，缺少任何一条都不会死锁）。")
add(kp,"以下哪种方法通过破坏“互斥”条件来预防死锁（）。","使用SPOOLing技术将独占设备虚拟化为共享设备",["一次性分配资源","允许抢占资源","资源有序分配"],"SPOOLing（假脱机）将独占设备（如打印机）改造为共享设备，破坏了互斥条件。","中等")
add(kp,"以下哪种方法通过破坏“占有且等待”条件来预防死锁（）。","要求进程在开始执行前一次性申请所有资源",["使用SPOOLing","允许抢占","资源有序分配"],"一次性分配所有资源（预分配）或当申请不到资源时释放已持有资源，破坏占有且等待。")
add(kp,"以下哪种方法通过破坏“不可抢占”条件来预防死锁（）。","允许操作系统强制收回进程持有的资源",["使用SPOOLing","一次性分配资源","资源有序分配"],"允许抢占：如果进程申请的资源被占用，OS可以强制收回该进程持有的资源。")
add(kp,"以下哪种方法通过破坏“循环等待”条件来预防死锁（）。","为资源编号，要求进程按编号顺序申请资源",["使用SPOOLing","一次性分配资源","允许抢占"],"资源有序分配（Resource Ordering）：为所有资源编号，进程必须按编号递增顺序申请资源。")
add(kp,"破坏“循环等待”条件的资源编号方法中，进程申请资源必须（）。","按编号递增顺序申请",["按编号递减顺序","随机顺序","同时申请"],"资源有序分配法：进程必须先申请编号小的资源，再申请编号大的资源，不能反向。")
add(kp,"以下关于死锁必要条件的“充分性”，描述正确的是（）。","四个条件同时满足是死锁的充分必要条件",["四个条件同时满足不一定死锁","满足三个条件即可","任何条件都充分"],"Coffman等人证明：在资源分配系统中，四个条件同时满足是死锁的充要条件。")
add(kp,"以下关于“破坏占有且等待”的不同实现方式，描述正确的是（）。","可以在申请前释放所有资源，也可以一次性申请所有资源",["只有一种实现方式","不需要实现","实现方式不影响效果"],"两种方式：①申请前释放所有已持有资源；②一次性申请所有所需资源。")
add(kp,"以下关于资源编号法预防死锁的缺点，描述正确的是（）。","难以找到满足所有进程的资源编号顺序",["实现简单","没有缺点","编号任意即可"],"资源编号法需要全局的编号顺序，但实际系统中资源种类繁多，难以找到对所有进程都合理的编号。")
add(kp,"以下关于死锁四个必要条件中“互斥”的描述，正确的是（）。","互斥是资源本身的特性，很难被破坏",["互斥很容易破坏","互斥不是必要条件","互斥与死锁无关"],"互斥是由资源固有特性决定的（如打印机不能同时打印两份文档），大部分情况下无法破坏。")
add(kp,"以下关于死锁必要条件的“发生顺序”，描述正确的是（）。","通常：互斥→占有且等待→不可抢占→循环等待，循环等待是最终表现",["循环等待先发生","互斥是最后发生","顺序无关"],"死锁的形成过程：资源互斥→进程持有资源并等待→资源不可抢占→形成循环等待链。")
add(kp,"以下哪项不是死锁的必要条件（）。","资源共享",["互斥","占有且等待","不可抢占"],"死锁的四个必要条件：互斥、占有且等待、不可抢占、循环等待。资源共享不是必要条件。")
add(kp,"在资源分配图中，如果出现环路，说明满足了（）条件。","循环等待",["互斥","占有且等待","不可抢占"],"资源分配图中的环路表示存在循环等待链，即满足了循环等待条件。")
add(kp,"以下关于死锁必要条件中“占有且等待”的典型场景，描述正确的是（）。","进程持有一台打印机，又申请一台扫描仪",["进程不持有任何资源","进程释放所有资源后申请","进程同时申请所有资源"],"占有且等待：进程已持有打印机（占有），又申请扫描仪并被阻塞（等待）。")
add(kp,"以下关于死锁必要条件中的“不可抢占”，描述错误的是（）。","CPU是不可抢占资源",["打印机是不可抢占资源","磁带机是不可抢占资源","数据库锁通常是不可抢占的"],"CPU是可抢占资源（进程调度会抢占CPU），打印机、文件等通常是不可抢占的。")
add(kp,"破坏死锁四个必要条件中的任何一个，就可以（）。","预防死锁的发生",["检测死锁","恢复死锁","避免死锁"],"死锁预防（Prevention）：破坏四个必要条件之一，使死锁不可能发生。")
add(kp,"以下关于死锁“预防”和“避免”的区别，描述正确的是（）。","预防破坏必要条件，避免动态判断是否安全",["预防和避免完全相同","预防是动态判断","避免是破坏条件"],"预防（Prevention）静态破坏条件，避免（Avoidance）动态判断资源分配是否会导致不安全状态。","中等")
add(kp,"以下关于死锁必要条件的最难破坏的是（）。","互斥条件",["占有且等待","不可抢占","循环等待"],"互斥条件由资源固有特性决定，很难破坏；其他三个条件可以通过策略破坏。","中等")
add(kp,"破坏“不可抢占”条件的方法中，如果进程申请资源失败，则（）。","释放已持有的所有资源，然后重新申请",["继续等待","终止进程","忽略申请"],"释放已持有资源+重新申请，类似事务回滚，代价较高。")
add(kp,"以下关于死锁必要条件，属于“Coffman条件”的是（）。","互斥、占有且等待、不可抢占、循环等待",["互斥、同步、通信、共享","互斥、并发、异步、等待","互斥、共享、虚拟、等待"],"这四个条件由Coffman、Elphick和Shoshani在1971年提出，是死锁的充要条件。")

# ===========================================
# 3.4.3 死锁的防止 (~55 questions)
# ===========================================
kp = "3.4.3"
add(kp,"死锁预防（Deadlock Prevention）的基本思想是（）。","破坏死锁四个必要条件中的一个或多个",["检测死锁然后恢复","动态判断是否安全","忽略死锁"],"死锁预防通过破坏互斥、占有且等待、不可抢占或循环等待中至少一个条件，使死锁不可能发生。")
add(kp,"以下关于死锁预防中破坏“互斥”条件的方法，描述正确的是（）。","使用SPOOLing技术将独占设备虚拟化为共享设备",["增加资源数量","减少进程数量","禁止使用资源"],"SPOOLing（如打印队列）将独占设备改造为共享设备，破坏互斥条件。")
add(kp,"SPOOLing技术预防死锁的典型应用是（）。","打印机共享",["CPU调度","内存管理","文件系统"],"打印机SPOOLing：进程将打印任务写入磁盘队列，打印机守护进程从队列取出打印，进程不直接竞争打印机。")
add(kp,"以下关于死锁预防中破坏“占有且等待”条件的协议一，描述正确的是（）。","进程在开始执行前一次性申请所有所需资源",["进程逐步申请资源","进程不申请资源","进程释放资源后不再申请"],"协议一（预分配）：进程必须一次性申请所有需要的资源，申请到所有资源后才开始执行。")
add(kp,"死锁预防中破坏“占有且等待”的协议一的主要缺点是（）。","资源利用率低（资源被持有但不一定使用），可能饥饿",["资源利用率高","实现简单","没有缺点"],"一次性分配所有资源导致资源被长期持有但闲置，且进程可能因总是申请不到全部资源而饥饿。")
add(kp,"以下关于死锁预防中破坏“占有且等待”条件的协议二，描述正确的是（）。","当进程申请的资源被占用时，释放已持有的所有资源",["一次性申请所有资源","不释放任何资源","申请资源后不释放"],"协议二：进程可以逐步申请资源，但申请失败时必须释放所有已持有的资源，然后重新申请。")
add(kp,"死锁预防中破坏“占有且等待”的协议二的主要缺点是（）。","可能导致活锁（反复申请-释放）",["资源利用率低","实现复杂","不能预防死锁"],"协议二可能导致进程反复申请-释放-申请，一直无法全部获得所需资源，形成活锁。","中等")
add(kp,"以下关于死锁预防中破坏“不可抢占”条件的方法，描述正确的是（）。","如果进程申请资源失败，OS强制收回已分配的资源",["进程主动释放资源","不分配资源","增加资源"],"破坏不可抢占：允许OS强制从持有资源的进程中收回资源，分配给等待的进程。")
add(kp,"以下哪种资源类型容易实现抢占（）。","CPU和内存（状态可保存和恢复）",["打印机","文件","数据库锁"],"CPU和内存的上下文可以保存和恢复，适合抢占；打印机等设备不适合抢占（打印到一半无法恢复）。","中等")
add(kp,"死锁预防中破坏“不可抢占”的缺点不包括（）。","实现简单，无性能影响",["需要保存/恢复资源状态","某些资源不适合抢占","增加了系统开销"],"破坏不可抢占需要保存和恢复资源状态，实现复杂，且某些资源语义上不适合抢占。")
add(kp,"以下关于死锁预防中破坏“循环等待”条件的方法，描述正确的是（）。","为所有资源类型编号，要求进程按编号递增顺序申请",["随机申请资源","不申请资源","按编号递减申请"],"资源有序分配法：为每类资源分配唯一编号，进程必须按编号递增顺序申请，不能反向。")
add(kp,"资源有序分配法预防死锁时，如果进程需要编号为3和5的资源，正确的申请顺序是（）。","先申请3，再申请5",["先申请5，再申请3","可以同时申请","顺序任意"],"按编号递增顺序：编号小的先申请，编号大的后申请。")
add(kp,"资源有序分配法预防死锁的缺点是（）。","难以找到对所有进程都适用的资源编号顺序",["不能预防死锁","实现太简单","不破坏循环等待"],"不同进程可能需要不同的资源申请顺序，全局统一的编号顺序很难满足所有进程。")
add(kp,"以下关于死锁预防的不同方法，哪种在实际系统中应用最广（）。","资源有序分配法（破坏循环等待）",["一次性分配（破坏占有且等待）","抢占资源（破坏不可抢占）","SPOOLing（破坏互斥）"],"资源有序分配法对系统性能影响较小，在数据库等系统中广泛应用。","中等")
add(kp,"死锁预防方法中，破坏“占有且等待”的两种协议对比，协议一（一次性分配）的优点是（）。","实现简单，不会活锁",["资源利用率高","可扩展性好","没有饥饿"],"协议一实现简单且不会活锁（要么全得要么全不得），但资源利用率低、可能饥饿。")
add(kp,"在数据库系统中，通常使用（）来预防死锁。","锁的层次顺序（如先锁表再锁行）",["一次性分配所有锁","抢占锁","SPOOLing"],"数据库通过规定锁的层次顺序（意向锁机制）来破坏循环等待条件。")
add(kp,"以下关于死锁预防的“策略选择”，描述正确的是（）。","破坏互斥和不可抢占较难，破坏占有且等待和循环等待较常用",["破坏互斥最常用","只破坏一个条件就够了","所有策略等价"],"互斥和不可抢占是资源固有特性难以破坏；破坏占有且等待和循环等待是实际系统中最常用的策略。")
