add(kp,"银行家算法中，当进程Pi请求资源时，首先检查（）。","Request[i] <= Need[i]（请求不超过声明的最大需求）",["Request[i] <= Available","Request[i] <= Max[i]","Request[i] <= Allocation[i]"],"第一步：检查请求是否超过进程声明的最大需求（防止欺诈）。第二步：检查是否超过可用资源。","中等")
add(kp,"银行家算法进行安全性检查时，Work向量表示（）。","当前可用的资源数量（模拟分配过程中）",["进程已分配的资源","进程需要的资源","进程最大需求"],"Work是安全性算法中的临时变量，初始等于Available，随着进程完成而增加。","中等")
add(kp,"银行家算法进行安全性检查时，Finish[i]表示（）。","进程i是否在模拟中完成",["进程i是否请求资源","进程i是否开始","进程i是否运行"],"Finish[i]是布尔值：true表示进程i在模拟中已完成，释放了资源。")
add(kp,"在银行家算法安全性检查中，如果找不到满足Need[i]<=Work的进程，则（）。","系统处于不安全状态",["系统处于安全状态","所有进程都已完成","算法错误"],"如果没有未完成进程的需求能被当前Work满足，说明无法推进，系统不安全。")
add(kp,"银行家算法的核心思想是（）。","类似银行放贷：只放贷给能还的客户，确保始终有足够资金周转",["一次性放贷所有资金","不检查客户信用","随机放贷"],"银行家算法类比：银行只有在保证能收回贷款的情况下才放贷，确保始终有资金满足其他客户。")
add(kp,"以下关于银行家算法的“资源请求算法”，描述正确的是（）。","假设请求合法→尝试分配→安全性检查→安全则分配，不安全则拒绝等待",["直接分配","拒绝所有请求","不检查安全性"],"流程：①检查Request<=Need；②检查Request<=Available；③尝试分配；④安全性检查；⑤安全则正式分配。","中等")
add(kp,"银行家算法的主要局限性是（）。","需要预先知道每个进程的最大资源需求，且进程数量需固定",["算法太复杂","不能预防死锁","只适用于单资源"],"银行家算法要求：①进程数量固定；②资源数量固定；③每个进程声明最大需求；④进程独立运行无同步要求。","中等")
add(kp,"银行家算法中，如果系统处于不安全状态，则（）。","可能死锁也可能不死锁",["一定死锁","一定不死锁","系统崩溃"],"不安全状态是死锁的必要条件不是充分条件：不安全状态可能死锁，但不一定发生。")
add(kp,"以下关于银行家算法的“资源类型”要求，描述正确的是（）。","每种资源数量固定，且资源类型和数量已知",["资源数量动态变化","资源类型未知","对资源无要求"],"银行家算法要求资源类型和数量在系统运行前已知且固定。")
add(kp,"如果系统中有5个进程和3种资源，银行家算法的Max矩阵大小是（）。","5×3",["3×5","5×5","3×3"],"Max矩阵：行=进程数（5），列=资源类型数（3），所以是5×3。")
add(kp,"在银行家算法中，Available向量初始等于（）。","系统各类资源的总数量",["所有进程的Max之和","所有进程的Need之和","无穷大"],"Available初始为系统所有资源的总数量（尚未分配任何资源时）。")
