add(kp,"在银行家算法中，当进程完成并释放所有资源后，Available向量应该（）。","增加（加上该进程已分配的资源）",["减少","不变","归零"],"进程完成后释放资源，Allocation[i]加到Available上，即Available += Allocation[i]。")
add(kp,"以下关于银行家算法的“Work”和“Finish”向量，描述正确的是（）。","安全性算法中Work初始=Available，Finish初始全false",["Work初始=Allocation","Finish初始全true","Work初始=Need"],"安全性算法：Work=Available（可用资源），Finish[i]=false（所有进程未完成）。")
add(kp,"安全性算法的每一步，选择一个满足（）的进程。","Need[i] <= Work 且 Finish[i] == false",["Max[i] <= Work","Allocation[i] <= Work","Need[i] <= Available"],"选择条件：未完成（Finish[i]==false）且需求不超过当前可用资源（Need[i]<=Work）。","中等")
add(kp,"安全性算法中，当选中进程i后，更新Work的方式是（）。","Work = Work + Allocation[i]",["Work = Work - Need[i]","Work = Work + Need[i]","Work = Work - Allocation[i]"],"假设进程i完成，释放其已分配资源：Work += Allocation[i]。")
