# ===========================================
# 3.4.5 死锁检测与恢复 (~55 questions)
# ===========================================
kp = "3.4.5"
add(kp,"死锁检测（Deadlock Detection）的基本思想是（）。","允许系统进入死锁状态，通过算法检测死锁的存在",["预防死锁发生","避免死锁","忽略死锁"],"死锁检测不阻止死锁发生，而是定期检测系统是否已经死锁，然后采取措施恢复。")
