add(kp,"以下关于死锁检测算法中“Work”和“Finish”向量，描述正确的是（）。","Work初始=Available，Finish初始：Allocation[i]==0则为true否则false",["Finish初始全true","Work初始=0","Finish初始全false"],"死锁检测算法：Work=Available；若Allocation[i]!=0则Finish[i]=false（可能有资源又可能等待）；若Allocation[i]==0则Finish[i]=true。")
add(kp,"在死锁检测算法中，选择进程i的条件是（）。","Request[i] <= Work 且 Finish[i] == false",["Need[i] <= Work","Max[i] <= Work","Allocation[i] <= Work"],"检测算法检查Request[i]（请求量）而非Need[i]（还需要的量），这是与银行家算法的区别。","中等")
add(kp,"死锁检测算法结束后，如果存在Finish[i]==false的进程，说明（）。","这些进程处于死锁状态",["系统安全","这些进程已完成","算法错误"],"Finish[i]仍为false表示进程i无法完成，陷入死锁。")
add(kp,"死锁检测的时机通常选择（）。","定期检测（如每隔一定时间）或当资源利用率异常低时检测",["每次资源分配时检测","从不检测","只有启动时检测"],"检测频率的权衡：太频繁开销大，太稀疏死锁持续时间长。通常定期或资源利用率过低时检测。")
add(kp,"死锁检测的代价相比死锁避免（）。","检测开销通常更小（因为检测频率低）",["检测开销更大","两者开销相同","检测不需要开销"],"死锁检测不需要每次资源分配都检查，定期检测即可，开销小于每次分配都检查的避免策略。")
add(kp,"死锁恢复（Recovery）的方法不包括（）。","预防死锁",["终止进程","回滚进程","抢占资源"],"死锁恢复是死锁已发生后的补救措施，包括：终止进程、资源抢占、回滚。预防是事前措施。")
add(kp,"以下关于死锁恢复中“终止进程”的方法，描述正确的是（）。","终止所有死锁进程或逐个终止直到死锁解除",["只终止一个进程","不终止进程","终止非死锁进程"],"两种终止策略：①终止所有死锁进程（简单但代价大）；②逐个终止直到死锁解除（开销小但需要反复检测）。")
add(kp,"死锁恢复中，选择“牺牲”进程（终止）的依据不包括（）。","进程的优先级越高越好",["进程已运行时间","进程还需运行时间","进程使用了多少资源"],"选择终止进程通常考虑：优先级（低优先级优先）、已运行时间（少优先）、还需时间（多优先）、资源使用（多优先）。","中等")
add(kp,"死锁恢复中，通过“抢占资源”来恢复死锁，描述正确的是（）。","从某些进程中强制收回资源分配给其他进程",["不回收资源","增加资源","终止所有进程"],"资源抢占（Preemption）：从死锁进程中强制收回资源，分配给其他进程以打破死锁。")
add(kp,"死锁恢复中，“回滚”（Rollback）是指（）。","将进程回退到死锁发生前的某个检查点",["终止进程","抢占资源","重新启动系统"],"回滚（检查点/Checkpoint）：进程定期保存状态，死锁时回退到最近检查点，释放资源。")
add(kp,"以下关于死锁恢复中“饥饿”问题的描述，正确的是（）。","如果总是选择同一个进程作为牺牲品，该进程可能饥饿",["不存在饥饿问题","所有进程都可能饥饿","饥饿不可解决"],"如果每次死锁都终止同一个进程，该进程可能永远无法完成，形成饥饿。","中等")
add(kp,"死锁检测算法中，对“等待图”（Wait-for Graph）的描述，正确的是（）。","等待图中节点是进程，边Pi→Pj表示Pi等待Pj释放资源",["节点是资源","边表示资源分配","等待图就是资源分配图"],"等待图是资源分配图的简化：从资源分配图中去掉资源节点，只保留进程间的等待关系。","中等")
add(kp,"对于每种资源单个实例的情况，等待图中有环等价于（）。","死锁发生",["系统安全","资源不足","无死锁"],"每种资源单实例：等待图中有环⇔死锁。这是死锁检测的简单方法。")
add(kp,"死锁检测算法的时间复杂度主要取决于（）。","进程数量和资源类型数量",["只有进程数量","只有资源类型","与数量无关"],"死锁检测算法复杂度类似安全性算法：O(n^2*m)，n为进程数，m为资源类型数。")
add(kp,"以下关于死锁检测和恢复的适用场景，描述正确的是（）。","适合死锁发生概率低的系统",["适合死锁发生概率高的系统","适合所有系统","不适合任何系统"],"死锁检测+恢复适合死锁发生概率低的场景（如通用操作系统），因为检测开销小且恢复代价可接受。")
add(kp,"在数据库系统中，死锁通常使用（）处理。","死锁检测与恢复（选择事务回滚）",["死锁预防","死锁避免","鸵鸟策略"],"数据库系统通常采用死锁检测+恢复：定期检测等待图，选择代价最小的事务回滚。")
add(kp,"以下关于死锁检测算法的“频率选择”，描述正确的是（）。","频率太高浪费CPU，频率太低死锁持续时间长",["总是检测","从不检测","频率不影响"],"需要在检测开销和死锁持续时间之间权衡，通常几分钟到几十分钟检测一次。")
add(kp,"死锁检测中，如果检测到死锁，操作系统的下一步是（）。","死锁恢复（终止进程或抢占资源）",["忽略死锁","继续等待","重新启动系统"],"检测到死锁后，需要采取措施恢复，不能忽略。")
add(kp,"以下关于死锁检测中“请求矩阵”（Request）和“银行家算法”中“需求矩阵”（Need）的区别，描述正确的是（）。","Request是当前实际请求，Need是还需的最大量",["两者完全相同","Request是最大值","Need是当前请求"],"死锁检测用Request（当前实际请求），银行家算法用Need（可能的最大需求）。","中等")
add(kp,"死锁恢复中，如果使用“抢占资源”方法，需要处理（）。","选择被抢占的进程、回滚、防止饥饿",["不需要处理","只抢占就行","不需要回滚"],"资源抢占需要考虑：①选择哪个进程？②回滚到哪里？③如何避免同一个进程总是被抢占（饥饿）？")

# ===========================================
# 3.4.6 两阶段加锁 (~55 questions)
# ===========================================
kp = "3.4.6"
add(kp,"两阶段加锁（Two-Phase Locking, 2PL）主要用于（）。","数据库系统中保证事务调度的可串行化",["CPU调度","内存管理","文件系统"],"2PL是数据库并发控制的基本协议，用于保证事务的隔离性和可串行化。")
add(kp,"两阶段加锁的“两个阶段”是指（）。","增长阶段（Growing Phase）和收缩阶段（Shrinking Phase）",["申请阶段和释放阶段","读阶段和写阶段","开始阶段和结束阶段"],"增长阶段：事务可以获取锁，不能释放锁；收缩阶段：事务可以释放锁，不能获取新锁。")
add(kp,"在两阶段加锁的增长阶段中，事务（）。","只能获取锁，不能释放任何锁",["可以释放锁","可以获取和释放锁","不能获取锁"],"增长阶段（Growing Phase）：事务不断获取需要的锁，不允许释放任何锁。")
add(kp,"在两阶段加锁的收缩阶段中，事务（）。","只能释放锁，不能获取新锁",["可以获取锁","可以获取和释放锁","不能释放锁"],"收缩阶段（Shrinking Phase）：事务释放锁，一旦释放了一个锁，就不能再获取新锁。")
add(kp,"两阶段加锁的“锁点”（Lock Point）是指（）。","事务获取最后一个锁的时刻（增长阶段结束的时刻）",["事务开始时刻","事务结束时刻","第一个锁释放时刻"],"锁点（Lock Point）是增长阶段结束的位置，之后事务进入收缩阶段。")
add(kp,"严格两阶段加锁（Strict 2PL）要求（）。","所有排他锁（X锁）在事务提交后才释放",["所有锁在事务提交前释放","不要求释放顺序","可以随时释放锁"],"严格2PL：排他锁（写锁）一直持有到事务提交（或回滚），防止脏读和级联回滚。")
add(kp,"强两阶段加锁（Rigorous 2PL）要求（）。","所有锁（共享锁和排他锁）在事务提交后才释放",["只持有排他锁","可以随时释放","不持有锁"],"强2PL（Rigorous/Conservative 2PL）：所有锁（包括共享锁）都保持到事务结束。")
add(kp,"两阶段加锁协议可以保证事务的（）。","可串行化（Serializability）",["不会死锁","不会饥饿","事务并行"],"2PL协议保证事务调度是可串行化的，即并发执行结果等价于某种串行执行结果。")
add(kp,"两阶段加锁协议不能保证防止（）。","死锁",["不可串行化调度","脏读","数据不一致"],"2PL可以保证可串行化，但不能防止死锁（事务可能因锁等待形成循环等待）。")
add(kp,"两阶段加锁协议可能导致的死锁，通常通过（）解决。","死锁检测和事务回滚",["破坏2PL协议","银行家算法","忽略死锁"],"数据库系统中，2PL导致的死锁通过死锁检测（等待图）和事务回滚来处理。")
add(kp,"以下关于两阶段加锁的“锁类型”，描述正确的是（）。","共享锁（S锁）和排他锁（X锁）",["只有共享锁","只有排他锁","没有锁类型"],"数据库锁：共享锁（S锁/读锁）允许多个事务持有；排他锁（X锁/写锁）只允许一个事务持有。")
add(kp,"共享锁（S锁）和排他锁（X锁）的兼容性，描述正确的是（）。","S锁与S锁兼容，S锁与X锁不兼容，X锁与X锁不兼容",["所有锁都兼容","所有锁都不兼容","S锁与X锁兼容"],"兼容矩阵：S-S兼容（多个事务可同时读），S-X不兼容，X-X不兼容（写需要独占）。")
add(kp,"两阶段加锁协议中，如果事务T需要修改数据项，它必须获取（）。","排他锁（X锁）",["共享锁（S锁）","不需要锁","任意锁"],"写操作需要排他锁（X锁），保证写期间没有其他事务读写。")
add(kp,"两阶段加锁协议中，如果事务T需要读取数据项，它需要获取（）。","共享锁（S锁）",["排他锁（X锁）","不需要锁","任意锁"],"读操作获取共享锁（S锁），允许多个事务同时读。")
add(kp,"以下关于锁升级（Lock Promotion）的描述，正确的是（）。","将共享锁升级为排他锁（需要在增长阶段完成）",["将排他锁升级为共享锁","释放锁后重新获取","不能升级锁"],"锁升级：事务先获取S锁读取数据，发现需要修改时升级为X锁。升级必须在增长阶段完成。")
add(kp,"锁降级（Lock Demotion）是指（）。","将排他锁降级为共享锁",["将共享锁降级为排他锁","释放所有锁","不能降级"],"锁降级：事务写完数据后不再需要修改，将X锁降为S锁，允许其他事务读。")
add(kp,"两阶段加锁协议中，以下关于“幻读”问题的描述，正确的是（）。","2PL不能完全防止幻读（新插入的数据），需要间隙锁",["2PL可以防止幻读","幻读不存在","幻读与2PL无关"],"基本2PL防止了不可重复读和脏读，但幻读（其他事务插入新数据）需要谓词锁/间隙锁（Index Locking）。","中等")
add(kp,"以下关于两阶段加锁协议的“级联回滚”问题，描述正确的是（）。","如果事务T1释放锁后T2读取了T1的数据，T1回滚会导致T2回滚",["不存在级联回滚","2PL防止级联回滚","级联回滚是好事"],"严格2PL（事务提交后才释放X锁）可以防止级联回滚。","中等")
add(kp,"两阶段加锁协议中，如果事务在收缩阶段申请新锁，会（）。","违反2PL协议，可能导致不可串行化调度",["正常执行","死锁","自动获取锁"],"2PL协议禁止在收缩阶段获取新锁，违反会导致不可串行化。")
add(kp,"保守两阶段加锁（Conservative 2PL）是指（）。","事务在开始执行前一次性获取所有需要的锁",["事务不获取锁","事务在结束时获取锁","事务随机获取锁"],"保守2PL（静态2PL）：事务预声明所有需要的数据项，在开始前一次性获取所有锁，避免死锁。")
add(kp,"保守两阶段加锁的主要缺点是（）。","锁持有时间长，并发度低",["可能死锁","不能保证可串行化","实现简单"],"保守2PL要求事务开始前获取所有锁，锁持有时间长，降低了并发度。")
add(kp,"两阶段加锁协议在分布式数据库系统中的应用，需要（）。","分布式死锁检测和分布式锁管理",["不需要修改","与单机完全相同","不需要锁"],"分布式2PL需要解决分布式锁管理、分布式死锁检测（可能跨节点）等额外问题。")
add(kp,"以下关于两阶段加锁和“时间戳排序”的比较，描述正确的是（）。","2PL是悲观并发控制，时间戳排序是乐观并发控制",["两者完全相同","2PL是乐观的","时间戳排序是悲观的"],"2PL假设冲突频繁（悲观），提前加锁；时间戳排序假设冲突少（乐观），提交时检查。")
add(kp,"两阶段加锁协议中，“意向锁”（Intention Lock）的作用是（）。","在多粒度锁层次中，表示要在下层节点加锁的意图",["表示事务的意图","不是锁","用于死锁检测"],"意向锁（IS/IX/SIX）用于多粒度封锁（如表级、行级），表示事务计划在更细粒度上加锁。","中等")

# ===========================================
# 3.4.7 活锁 (~55 questions)
# ===========================================
kp = "3.4.7"
add(kp,"活锁（Livelock）是指（）。","进程不断改变状态但无法推进，类似于两个人在走廊互相让路",["进程无限期等待","进程正常执行","进程被终止"],"活锁：进程虽没有被阻塞，但由于不断重复某种操作（如释放-申请），始终无法取得进展。")
add(kp,"活锁和死锁的主要区别是（）。","死锁中进程被阻塞，活锁中进程在运行但无法推进",["两者完全相同","活锁比死锁更严重","活锁中进程被阻塞"],"死锁：进程阻塞等待（不消耗CPU）；活锁：进程在运行（消耗CPU）但不断重复无用操作。","中等")
add(kp,"以下关于活锁的经典例子，描述正确的是（）。","两个人在走廊相遇，同时向左让又同时向右让，始终无法通过",["进程等待资源","进程终止","进程正常运行"],"活锁的经典比喻：两人在走廊互相让路，但总是让到同一方向，始终无法错开。")
add(kp,"活锁通常发生在（）场景。","进程尝试解决死锁但方法不当（如反复释放-重新申请资源）",["进程正常运行","进程等待资源","进程终止"],"活锁常见于：死锁预防的协议二（释放-申请）、以太网CSMA/CD冲突退避等。")
add(kp,"以下关于死锁预防协议二导致活锁的描述，正确的是（）。","进程反复释放已持有资源并重新申请，一直无法获得全部资源",["进程正常运行","进程被阻塞","进程终止"],"协议二：申请不到资源时释放所有资源，可能导致进程反复执行释放-申请循环，形成活锁。","中等")
add(kp,"在以太网中，CSMA/CD协议中如果发生冲突，二进制指数退避算法可能导致（）。","多次冲突后退避时间越来越长，但理论上可能无限重试（活锁）",["立即发送成功","死锁","网络断开"],"以太网冲突后等待随机时间重试，如果持续冲突，退避时间指数增长，但理论上可能永远无法成功发送（活锁）。","中等")
add(kp,"以下关于活锁的解决方法，描述正确的是（）。","为进程引入随机等待时间，打破对称的操作模式",["终止所有进程","增加资源","忽略活锁"],"活锁源于对称的重复操作，引入随机性（如随机退避时间）可以打破对称，让其中一个进程先成功。")
add(kp,"在解决活锁时，随机退避（Random Backoff）的作用是（）。","打破进程间的对称性，使某个进程先成功",["增加等待时间","减少等待时间","不改变任何行为"],"随机退避使得不同进程等待不同时间，其中一个进程将先获得资源/成功，打破活锁。")
add(kp,"活锁中进程的状态是（）。","就绪或运行（进程没有被阻塞，但无法推进）",["阻塞","终止","挂起"],"活锁中进程没有被阻塞，可以运行，但由于不断重复操作而无法取得实际进展。")
add(kp,"以下关于活锁和饥饿的区别，描述正确的是（）。","活锁中进程在运行但无法推进，饥饿中进程在等待但可能从未获得资源",["活锁和饥饿完全相同","活锁中进程被阻塞","饥饿中进程在运行"],"活锁：进程在“动”但无进展；饥饿：进程在“等”且可能永远等不到。","中等")
add(kp,"在并发编程中，以下哪种操作可能导致活锁（）。","两个线程互相谦让锁（一个线程释放锁让另一个线程获取）",["正确使用锁","单线程执行","不使用锁"],"如果两个线程都“太礼貌”，互相释放锁让对方获取，可能导致活锁。")
add(kp,"以下关于活锁的“资源消耗”描述，正确的是（）。","活锁消耗CPU但不产生有效进展",["活锁不消耗CPU","活锁消耗内存","活锁没有资源消耗"],"活锁中进程不断运行（消耗CPU），但始终无法完成有效工作，资源浪费。")
add(kp,"在数据库系统中，处理死锁的“等待-死亡”（Wait-Die）或“伤害-等待”（Wound-Wait）策略可以（）。","防止活锁（通过时间戳确定优先级）",["导致活锁","不影响活锁","忽略活锁"],"这些策略使用事务的时间戳来确定优先级，避免了对称的释放-申请，防止活锁。")
add(kp,"以下关于活锁检测的描述，正确的是（）。","活锁检测比死锁检测更困难，因为进程状态在变化",["活锁检测比死锁检测简单","活锁不需要检测","活锁和死锁检测相同"],"活锁中进程状态不断变化，不像死锁有明显的不变特征，检测更困难。","中等")
add(kp,"以下关于活锁预防的描述，正确的是（）。","避免对称的操作模式，引入随机性或优先级",["什么也不做","增加资源","终止进程"],"预防活锁：避免多个进程执行完全对称的操作；引入随机性；设置优先级打破对称。")
add(kp,"以下关于活锁和“自旋锁忙等”的区别，描述正确的是（）。","自旋锁忙等最终能获得锁并推进，活锁始终无法推进",["两者完全相同","自旋锁忙等是活锁","活锁最终能推进"],"自旋锁忙等：等待锁，一旦获得锁就能推进；活锁：即使获得资源也可能因操作模式而无法推进。","中等")
add(kp,"在操作系统中，以下哪种调度策略可能导致活锁（）。","优先级反转后的优先级继承协议",["FIFO调度","轮转调度","公平调度"],"不正确的优先级处理可能导致低优先级进程占有的资源被高优先级不断抢占，形成活锁。","中等")
add(kp,"解决活锁的“指数退避”（Exponential Backoff）算法中，每次冲突后等待时间（）。","翻倍（指数增长）",["减半","不变","随机"],"指数退避：第i次冲突后等待时间=随机(0, 2^i-1)个时间单位，时间上限指数增长。")
add(kp,"以下关于活锁和死锁的“可恢复性”，描述正确的是（）。","活锁和死锁都需要外部干预或特殊机制来恢复",["活锁可以自动恢复","死锁可以自动恢复","都不需要恢复"],"两者都需要特殊处理：死锁需要终止进程/抢占资源；活锁需要引入随机性打破对称。")
