add(kp,"以下哪种锁机制可能导致饥饿（）。","非公平锁（唤醒时不保证顺序，随机唤醒）",["公平锁（FIFO）","MCS锁","排队锁"],"非公平锁可能让某些进程反复被“插队”，长期得不到锁，导致饥饿。")
add(kp,"以下关于“老化”（Aging）技术的描述，正确的是（）。","随着进程等待时间增加，逐步提高其优先级",["降低进程优先级","保持优先级不变","终止进程"],"老化（Aging）是解决饥饿的常用技术：等待越久，优先级越高，最终获得资源。")
