# 3.6 多核环境下的进程同步 (~55 questions)
# ===========================================
kp = "3.6"
add(kp,"在多核环境下，进程同步面临的新挑战是（）。","多个核心真正同时执行，传统的单核同步机制可能不足",["同步更简单","不需要同步","与单核完全相同"],"多核环境下，多个进程真正并行执行，对临界区的竞争更激烈，同步开销更大。")
add(kp,"多核环境下，以下哪种同步机制会因“忙等”造成性能问题（）。","自旋锁（Spinlock）",["信号量","管程","条件变量"],"自旋锁在多核中：持有锁的核心在运行，等待的核心也在空转消耗CPU，可能影响持有锁核心的性能。","中等")
add(kp,"多核环境下，自旋锁（Spinlock）的优点不包括（）。","适合长时间持有锁的场景",["不需要上下文切换","实现简单延迟低","适合短临界区"],"自旋锁适合极短临界区（<上下文切换开销），长时间持有锁会导致其他核心空转浪费CPU。")
add(kp,"在多核环境中，以下哪种同步机制会产生“缓存一致性”（Cache Coherence）开销（）。","所有共享内存的同步机制（自旋锁、信号量等）",["只有信号量","只有管程","不需要"],"多核共享内存系统需要维护缓存一致性，对锁变量的修改需要在核心间同步缓存，产生额外开销。","中等")
add(kp,"MCS锁（Mellor-Crummey和Scott锁）是一种（）。","基于队列的自旋锁，每个核心在自己的缓存行上自旋",["互斥锁","信号量","读写锁"],"MCS锁：每个等待的核心在自己的局部变量上自旋，不在共享变量上自旋，大幅减少缓存一致性流量。")
add(kp,"以下关于MCS锁的优点，描述正确的是（）。","减少缓存一致性开销（每个核心在自己的缓存行上自旋）",["实现简单","适合长临界区","不需要自旋"],"MCS锁（以及CLH锁）通过本地自旋避免全局自旋的缓存颠簸（Cache Thrashing）。","中等")
add(kp,"RCU（Read-Copy-Update）是一种（）。","主要用于读多写少场景的同步机制，允许读者无锁访问",["写者优先锁","读者优先锁","自旋锁"],"RCU：读者完全不获取锁（无等待），写者创建副本修改然后原子替换指针，适用于读多写少场景。")
add(kp,"RCU的“宽限期”（Grace Period）是指（）。","写者更新数据后，等待所有可能引用旧数据的读者完成的时间",["读者读取时间","写者修改时间","系统启动时间"],"Grace Period：写者修改后必须等待所有可能正在读旧数据的读者完成，然后才能释放旧数据。")
add(kp,"RCU的适用场景是（）。","读操作频繁、写操作稀少的场景",["写操作频繁","读写均衡","不适合任何场景"],"RCU非常适合读密集场景（如路由表、内核数据结构），因为读者零开销。","中等")
